vergleichsmiete_ausgleich_und_drittmittel <- function(ausgangsmiete_drei_jahre=NULL, nicht_anzurechnende_erhoehungen=NULL, derzeitige_monatsmiete=NULL, ortsuebliche_vergleichsmiete=NULL, gueltige_fuenfzehnprozent_verordnung=NULL, kapitalzuschuesse_559a_1=NULL, jaehrliche_zinsermaessigung=NULL, jaehrliche_laufende_foerderung=NULL, letzte_monatliche_ausgleichszahlung=NULL, ausnahmemodell=NULL, methodennachweis=NULL) {
 basis <- .geld(ausgangsmiete_drei_jahre);aus <- .geld(nicht_anzurechnende_erhoehungen);alt <- .geld(derzeitige_monatsmiete);v <- .geld(ortsuebliche_vergleichsmiete);fuenfzehn <- .wahrheitswert(gueltige_fuenfzehnprozent_verordnung,'gueltige_fuenfzehnprozent_verordnung');z <- .geld(kapitalzuschuesse_559a_1);zins <- .geld(jaehrliche_zinsermaessigung);laufend <- .geld(jaehrliche_laufende_foerderung);a <- .geld(letzte_monatliche_ausgleichszahlung);.text(methodennachweis,'methodennachweis');.auswahl(ausnahmemodell,'ausnahmemodell',c('alternative_erhoehungsgrenze','zusaetzlicher_ausnahmebetrag'))
 kleiner <- function(a,b) if(.vergleichen(a,b)<0)a else b
 groesser <- function(a,b) if(.vergleichen(a,b)>0)a else b
 abzug <- .addieren(.addieren(.multiplizieren(z,.bruch(2,25)),zins),laufend);vergleich <- groesser(.subtrahieren(v,.multiplizieren(abzug,.bruch(1,12))),.bruch(0))
 kappung <- .addieren(.multiplizieren(basis,.bruch(if(fuenfzehn)115 else 120,100)),aus);spielraum <- groesser(.subtrahieren(kappung,alt),.bruch(0))
 alternativ <- groesser(alt,kleiner(vergleich,.addieren(alt,groesser(spielraum,a))));additiv <- groesser(alt,kleiner(vergleich,.addieren(.addieren(alt,spielraum),a)));wahl <- if(ausnahmemodell=='alternative_erhoehungsgrenze')alternativ else additiv
 wert <- list(jaehrlicher_drittmittelabzug=.bruchteile(abzug),vergleichsmiete_nach_drittmitteln=.bruchteile(vergleich),monatsmiete_alternativmodell=.bruchteile(alternativ),monatsmiete_additionsmodell=.bruchteile(additiv),monatsmiete_nach_vorgegebenem_modell=.bruchteile(wahl),erhoehungsbetrag=.bruchteile(.subtrahieren(wahl,alt)))
 eingaben <- list(ausgangsmiete_drei_jahre=ausgangsmiete_drei_jahre, nicht_anzurechnende_erhoehungen=nicht_anzurechnende_erhoehungen, derzeitige_monatsmiete=derzeitige_monatsmiete, ortsuebliche_vergleichsmiete=ortsuebliche_vergleichsmiete, gueltige_fuenfzehnprozent_verordnung=gueltige_fuenfzehnprozent_verordnung, kapitalzuschuesse_559a_1=kapitalzuschuesse_559a_1, jaehrliche_zinsermaessigung=jaehrliche_zinsermaessigung, jaehrliche_laufende_foerderung=jaehrliche_laufende_foerderung, letzte_monatliche_ausgleichszahlung=letzte_monatliche_ausgleichszahlung, ausnahmemodell=ausnahmemodell, methodennachweis=methodennachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_VERGLEICHSMIETE_AUSGLEICH_UND_DRITTMITTEL",eingaben,list(list(operation="558V-F\u00f6rderabzug berechnen und bereinigte Vergleichsmiete mit zwei ausdr\u00fccklich qualifizierten558IV-Kappungsmodellen verbinden.")),eingaben)
 ergebnis$hinweise <- list("558V:8%der559aI-Zusch\u00fcsse plus j\u00e4hrliche Zinserm\u00e4\u00dfigung und laufende F\u00f6rderbetr\u00e4ge vom Jahresbetrag der Vergleichsmiete abziehen, f\u00fcr Monatsgrenze durch12. Nicht den Zuschuss selbst als Jahresabzug und nicht nochmals von bereits bereinigter Vergleichsmiete abziehen. Regul\u00e4re Kappung aus Dreijahresbasis*1.15oder1.20plusausgenommenen Erh\u00f6hungen.558IV-Konkurrenz rechtlich zwingend w\u00e4hlen: alternativeErh\u00f6hungsgrenze=max(regul\u00e4rer positiver Erh\u00f6hungsspielraum,Ausgleichszahlung); zus\u00e4tzlicherAusnahmebetrag=regul\u00e4rer positiver Spielraum+Ausgleichszahlung. Beide bedingten Wege werden ausgewiesen, keine allgemein best\u00e4tigte Addition behauptet. Vergleichsmiete nach F\u00f6rderung bleibt in beiden Varianten Obergrenze. Bereits dar\u00fcber liegende Bestandsmiete wird nicht automatisch gesenkt; nur positiver neuer Erh\u00f6hungsbetrag. Antwort-/Vorlauffristen und Wirksamkeit gesondert.")
 ergebnis
}
